import React from 'react';
import { FaSmile, FaMeh, FaFrown, FaAngry, FaGrinStars } from 'react-icons/fa';

function MoodTracker({ selectedMood, setSelectedMood }) {
  const moods = [
    { emoji: <FaGrinStars size={32} />, label: 'Excellent', color: '#2ecc71', value: 'excellent' },
    { emoji: <FaSmile size={32} />, label: 'Good', color: '#3498db', value: 'good' },
    { emoji: <FaMeh size={32} />, label: 'Okay', color: '#f39c12', value: 'okay' },
    { emoji: <FaFrown size={32} />, label: 'Low', color: '#e67e22', value: 'low' },
    { emoji: <FaAngry size={32} />, label: 'Stressed', color: '#e74c3c', value: 'stressed' },
  ];

  const handleMoodSelect = (mood) => {
    setSelectedMood(mood.value);
    const today = new Date().toDateString();
    const moods = JSON.parse(localStorage.getItem('moodHistory') || '{}');
    moods[today] = mood.value;
    localStorage.setItem('moodHistory', JSON.stringify(moods));
    alert(`Mood logged: ${mood.label}! Keep taking care of yourself. 💙`);
  };

  return (
    <div style={styles.container}>
      {moods.map((mood) => (
        <div
          key={mood.value}
          style={{
            ...styles.moodCard,
            ...(selectedMood === mood.value ? { ...styles.moodCardActive, borderColor: mood.color } : {}),
          }}
          onClick={() => handleMoodSelect(mood)}
        >
          <div style={{ ...styles.moodEmoji, color: mood.color }}>{mood.emoji}</div>
          <span style={styles.moodLabel}>{mood.label}</span>
        </div>
      ))}
    </div>
  );
}

const styles = {
  container: {
    display: 'flex',
    gap: '15px',
    justifyContent: 'space-between',
    flexWrap: 'wrap',
  },
  moodCard: {
    flex: 1,
    minWidth: '80px',
    background: 'white',
    padding: '15px',
    borderRadius: '15px',
    textAlign: 'center',
    cursor: 'pointer',
    transition: 'all 0.3s ease',
    boxShadow: '0 2px 10px rgba(0,0,0,0.05)',
  },
  moodCardActive: {
    transform: 'scale(1.05)',
    boxShadow: '0 5px 20px rgba(0,0,0,0.1)',
    border: '2px solid',
  },
  moodEmoji: {
    marginBottom: '10px',
  },
  moodLabel: {
    fontSize: '12px',
    fontWeight: '500',
  },
};

export default MoodTracker;
